import { installment, schedule, ledger, nextDue, addMonths } from './finance.mjs';

const KEY='crispy-credito-demo-v1';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(Math.round(v));
const date=v=>new Intl.DateTimeFormat('es-CO',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(v+'T12:00:00Z'));
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Bogota',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const uid=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),v=>v.toString(16).padStart(2,'0')).join('');
const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',wallet:'<path d="M20 8V5a2 2 0 0 0-2-2H5a3 3 0 0 0 0 6h16v11H5a3 3 0 0 1-3-3V6"/><path d="M21 12h-6v5h6"/><path d="M17 14.5h.01"/>',arrows:'<path d="M3 7h17m-4-4 4 4-4 4M21 17H4m4-4-4 4 4 4"/>',settings:'<path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/><circle cx="12" cy="12" r="7"/><circle cx="12" cy="12" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',up:'<path d="m3 17 6-6 4 4 8-11m-6 0h6v6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18m-12 4h.01M12 15h.01M15 15h.01"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v5m0-9h.01"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8M8 17h5"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6z"/><path d="m8 12 3 3 5-6"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[k]||paths.file}</svg>`;
function seed(){
  const now=today(), last=addMonths(now,-1), older=addMonths(now,-2);
  return {version:1,clients:[
    {id:'c1',name:'Valentina Torres',phone:'300 000 0001',note:'Cliente ficticio para explorar el prototipo.',createdAt:older},
    {id:'c2',name:'Andrés Martínez',phone:'300 000 0002',note:'Datos de ejemplo.',createdAt:older},
    {id:'c3',name:'Camila Rodríguez',phone:'300 000 0003',note:'Datos de ejemplo.',createdAt:last},
    {id:'c4',name:'Juan Sebastián López',phone:'300 000 0004',note:'Datos de ejemplo.',createdAt:last},
    {id:'c5',name:'Daniela Castro',phone:'300 000 0005',note:'Datos de ejemplo.',createdAt:now}
  ],loans:[
    {id:'l1',clientId:'c1',principal:1500000,rate:1.5,months:6,start:older,note:'Préstamo ficticio de ejemplo.'},
    {id:'l2',clientId:'c2',principal:2000000,rate:1.5,months:8,start:last,note:''},
    {id:'l3',clientId:'c3',principal:800000,rate:1.5,months:4,start:last,note:''},
    {id:'l4',clientId:'c4',principal:1200000,rate:1.5,months:6,start:last,note:''},
    {id:'l5',clientId:'c5',principal:500000,rate:0,months:5,start:now,note:'Ejemplo sin intereses.'}
  ],payments:[
    {id:'p1',loanId:'l1',capital:240000,interest:22500,date:last,method:'Transferencia',note:'Abono ficticio.',createdAt:last+'T12:00:00Z'},
    {id:'p2',loanId:'l2',capital:237000,interest:30000,date:now,method:'Transferencia',note:'Abono ficticio.',createdAt:now+'T10:00:00Z'},
    {id:'p3',loanId:'l1',capital:243600,interest:18900,date:now,method:'Efectivo',note:'Abono ficticio.',createdAt:now+'T11:00:00Z'}
  ]};
}
let storageAvailable=true, data;
try{const saved=localStorage.getItem(KEY);data=saved?validateImport(JSON.parse(saved)):seed();}catch{data=seed();storageAvailable=false;}
let query='',filter='todos';
function persist(){try{localStorage.setItem(KEY,JSON.stringify(data));}catch{storageAvailable=false;toast('No se pudo guardar. Descarga un respaldo antes de salir.');} }
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function client(id){return data.clients.find(c=>c.id===id);}
function loan(id){return data.loans.find(l=>l.id===id);}
function totals(loans=data.loans){return loans.reduce((t,l)=>{const a=ledger(l,data.payments);return {principal:t.principal+l.principal,balance:t.balance+a.balance,interest:t.interest+a.paidInterest,paid:t.paid+a.paidPrincipal};},{principal:0,balance:0,interest:0,paid:0});}
function initials(name){return name.trim().split(/\s+/).slice(0,2).map(n=>n[0]).join('').toUpperCase();}
function person(c,i=0,sub=''){return `<span class="person"><span class="person-avatar ${['','blue','peach','lavender'][i%4]}">${esc(initials(c.name))}</span><span><strong>${esc(c.name)}</strong><small>${esc(sub||c.phone||'Sin teléfono')}</small></span></span>`;}
function route(){const [page='inicio',id]=location.hash.slice(1).split('/');return {page,id};}
function go(hash){if(location.hash==='#'+hash)render();else location.hash=hash;}
function button(label,action,kind='',ico='',attrs=''){return `<button type="button" class="btn ${kind}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${label}</button>`;}
function badge(l){const a=ledger(l,data.payments);if(!a.balance)return '<span class="badge blue">Finalizado</span>';const next=nextDue(l,data.payments);return next&&next.date<today()?'<span class="badge orange">Por revisar</span>':'<span class="badge">En curso</span>';}
function clientBadge(c){const loans=data.loans.filter(l=>l.clientId===c.id);if(!loans.length)return '<span class="badge gray">Sin préstamos</span>';return loans.some(l=>ledger(l,data.payments).balance>0)?'<span class="badge">Activo</span>':'<span class="badge blue">Al día</span>';}
function stats(cards){return `<div class="stats">${cards.map(c=>`<div class="stat"><div class="stat-top"><span>${c.label}</span><span class="stat-icon">${icon(c.icon)}</span></div><div class="money">${c.value}</div><div class="stat-foot">${c.foot}</div></div>`).join('')}</div>`;}
function heading(title,subtitle,buttons='',eyebrow='TU CARTERA, EN ORDEN'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="buttons">${buttons}</div></div>`;}
function empty(title,text){return `<div class="empty">${icon('file')}<strong>${title}</strong>${text}</div>`;}
function clientTable(clients,compact=false){return `<div class="table-wrap"><table><thead><tr><th>CLIENTE</th><th>SALDO DE CAPITAL</th><th>PRÉSTAMOS</th><th>ESTADO</th><th></th></tr></thead><tbody>${clients.map((c,i)=>{const ls=data.loans.filter(l=>l.clientId===c.id),t=totals(ls);return `<tr class="clickable" data-action="client" data-id="${esc(c.id)}"><td>${person(c,i,compact?`${ls.length} préstamo${ls.length!==1?'s':''}`:'')}</td><td class="cell-money">${money(t.balance)}</td><td>${ls.length}</td><td>${clientBadge(c)}</td><td><button class="row-arrow" data-action="client" data-id="${esc(c.id)}" aria-label="Consultar ${esc(c.name)}">${icon('arrow')}</button></td></tr>`;}).join('')}</tbody></table></div>`;}
function upcoming(){return data.loans.map(l=>({loan:l,due:nextDue(l,data.payments)})).filter(x=>x.due).sort((a,b)=>a.due.date.localeCompare(b.due.date));}
function overview(){const t=totals(),active=data.loans.filter(l=>ledger(l,data.payments).balance>0),due=upcoming();
  return heading('Hola, Ángel <span style="font-size:23px;color:#b8c78e">✦</span>','Un vistazo a tus préstamos y a lo que viene.',button('Descargar respaldo','export','secondary-action','download')+button('Nuevo cliente','new-client','primary','plus'))+
  `<section class="hero"><div class="hero-copy"><div class="eyebrow">MENOS ENREDOS. MÁS TRANQUILIDAD.</div><h2>Tus cuentas claras,<br><span>tus metas más cerca.</span></h2><p>Clientes, préstamos y abonos. Todo en un solo lugar.</p><div class="hero-chip"><i></i> ${active.length} préstamos en curso · ${data.clients.length} clientes registrados</div></div><div class="hero-summary"><div class="hero-label">${icon('wallet')} Capital por recuperar</div><div class="money">${money(t.balance)}</div><small>Capital desembolsado menos abonos a capital</small></div></section>`+
  stats([{label:'Capital desembolsado',value:money(t.principal),icon:'wallet',foot:'Acumulado de todos tus préstamos'},{label:'Capital recuperado',value:money(t.paid),icon:'arrows',foot:'<span class="green">Abonos a capital registrados</span>'},{label:'Intereses recibidos',value:money(t.interest),icon:'up',foot:'Separados del capital recuperado'},{label:'Clientes registrados',value:String(data.clients.length).padStart(2,'0'),icon:'users',foot:`${active.length} préstamos con saldo pendiente`}])+
  `<div class="main-grid"><section class="panel"><div class="panel-heading"><div><h2>Tus clientes</h2><p>Cada historia, con sus cuentas claras.</p></div>${button('Ver todos ↗','clients','link')}</div>${data.clients.length?clientTable(data.clients.slice(0,5),true):empty('Tu primer cliente empieza aquí','Agrega una persona para registrar su préstamo.')}<div class="panel-foot"><span>${data.clients.length} clientes en tu espacio</span><button data-action="new-client">+ Agregar cliente</button></div></section><section class="panel"><div class="panel-heading"><div><h2>Próximas cuotas</h2><p>Según el calendario inicial.</p></div><span class="tag">${due.length} pendientes</span></div><div class="payment-list">${due.slice(0,4).map(x=>{const d=new Date(x.due.date+'T12:00:00Z');return `<div class="payment-item"><span class="date-tile"><b>${d.getUTCDate()}</b><small>${d.toLocaleDateString('es-CO',{month:'short',timeZone:'UTC'}).replace('.','').toUpperCase()}</small></span><span class="payment-info"><strong>${esc(client(x.loan.clientId).name.split(' ').slice(0,2).join(' '))}</strong><small>Cuota ${x.due.number} de ${x.loan.months}</small></span><span class="payment-value"><strong>${money(x.due.total)}</strong><small>${x.due.date<today()?'Por revisar':'Programada'}</small></span><button class="row-arrow" data-action="client" data-id="${esc(x.loan.clientId)}" aria-label="Ver préstamo">${icon('arrow')}</button></div>`;}).join('')||empty('Sin cuotas pendientes','Los nuevos préstamos aparecerán aquí.')}</div><div class="subtle-note">${icon('info')}<span>Calendario orientativo. Los abonos extraordinarios requieren revisar el acuerdo del préstamo.</span></div></section></div>`+
  `<div class="bottom-grid"><section class="panel"><div class="panel-heading"><div><h2>Últimos movimientos</h2><p>Lo que ha pasado en tu cartera.</p></div>${button('Ver historial ↗','payments','link')}</div><div class="activity-list">${data.payments.filter(p=>!p.reversed).slice().sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt)).slice(0,3).map(p=>`<div class="activity"><span class="activity-icon">${icon('check')}</span><div class="activity-text"><strong>Abono de ${esc(client(loan(p.loanId).clientId).name.split(' ')[0])}</strong><small>${date(p.date)} · ${esc(p.method)}</small></div><span class="activity-value">+ ${money(p.capital+p.interest)}</span></div>`).join('')||empty('Aún no hay abonos','Aquí verás los pagos que registres.')}</div></section><section class="panel"><div class="panel-heading"><div><h2>Así va tu capital</h2><p>El recorrido de tu dinero, sin mezclar intereses.</p></div><span class="stat-icon">${icon('up')}</span></div><div class="portfolio"><div class="portfolio-total"><strong>${t.principal?Math.round(t.paid/t.principal*100):0}%</strong><small>del capital recuperado</small></div><div class="portfolio-bar"><span style="width:${t.principal?t.paid/t.principal*100:0}%"></span><span style="width:${t.principal?t.balance/t.principal*100:0}%"></span></div><div class="legend"><div><i></i>Recuperado<b>${money(t.paid)}</b></div><div><i></i>Pendiente<b>${money(t.balance)}</b></div><div><i></i>Interés recibido<b>${money(t.interest)}</b></div></div></div></section></div>`;
}
function clientsView(){let list=data.clients.filter(c=>(c.name+' '+c.phone).toLocaleLowerCase().includes(query.toLocaleLowerCase()));if(filter==='activos')list=list.filter(c=>data.loans.some(l=>l.clientId===c.id&&ledger(l,data.payments).balance>0));
  return heading('Tus clientes','Una ficha para cada persona. Un historial siempre a mano.',button('Nuevo cliente','new-client','primary','plus'))+`<div class="toolbar"><label class="search">${icon('search')}<input id="search" aria-label="Buscar cliente" placeholder="Buscar por nombre o teléfono…" value="${esc(query)}"></label><div class="tabs"><button data-action="filter" data-value="todos" class="${filter==='todos'?'selected':''}">Todos los clientes</button><button data-action="filter" data-value="activos" class="${filter==='activos'?'selected':''}">Con saldo pendiente</button></div></div><section class="panel">${list.length?clientTable(list):empty('No hay clientes para mostrar','Prueba otra búsqueda o agrega un nuevo cliente.')}<div class="panel-foot">${list.length} resultados</div></section>`;
}
function loansView(){const list=data.loans.filter(l=>{const term=(client(l.clientId).name+' '+l.id).toLocaleLowerCase();const match=term.includes(query.toLocaleLowerCase());return match&&(filter==='todos'||(filter==='activos'?ledger(l,data.payments).balance>0:ledger(l,data.payments).balance===0));});
  return heading('Préstamos','Todos tus acuerdos, organizados y con su saldo de capital.',button('Nuevo préstamo','new-loan','primary','plus'))+`<div class="toolbar"><label class="search">${icon('search')}<input id="search" aria-label="Buscar préstamo" placeholder="Buscar por cliente…" value="${esc(query)}"></label><div class="tabs">${[['todos','Todos'],['activos','En curso'],['finalizados','Finalizados']].map(([id,label])=>`<button data-action="filter" data-value="${id}" class="${filter===id?'selected':''}">${label}</button>`).join('')}</div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>CLIENTE</th><th>DESEMBOLSO</th><th>SALDO CAPITAL</th><th>INTERÉS MENSUAL</th><th>CUOTAS</th><th>ESTADO</th><th></th></tr></thead><tbody>${list.map((l,i)=>`<tr><td>${person(client(l.clientId),i,date(l.start))}</td><td class="cell-money">${money(l.principal)}</td><td class="cell-money">${money(ledger(l,data.payments).balance)}</td><td>${l.rate.toLocaleString('es-CO')}%</td><td>${l.months} mensuales</td><td>${badge(l)}</td><td><button class="row-arrow" data-action="client" data-id="${esc(l.clientId)}" aria-label="Ver ficha">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>${!list.length?empty('Aún no hay préstamos aquí','Crea un préstamo para empezar a llevar su historial.'):''}</section>`;
}
function paymentsTable(payments,showClient=true){return `<div class="table-wrap"><table><thead><tr><th>FECHA</th>${showClient?'<th>CLIENTE</th>':''}<th>CAPITAL</th><th>INTERÉS</th><th>TOTAL</th><th>MEDIO</th><th></th></tr></thead><tbody>${payments.slice().sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt)).map(p=>`<tr ${p.reversed?'style="opacity:.55"':''}><td>${date(p.date)}</td>${showClient?`<td>${esc(client(loan(p.loanId).clientId).name)}</td>`:''}<td class="cell-money">${money(p.capital)}</td><td>${money(p.interest)}</td><td class="cell-money">${money(p.capital+p.interest)}</td><td>${esc(p.method)}</td><td>${p.reversed?'<span class="badge gray">Anulado</span>':`<button class="btn small ghost" data-action="payment-detail" data-id="${esc(p.id)}">Ver detalle</button>`}</td></tr>`).join('')}</tbody></table></div>`;}
function paymentsView(){const list=data.payments.filter(p=>(client(loan(p.loanId).clientId).name+' '+p.method).toLocaleLowerCase().includes(query.toLocaleLowerCase()));return heading('Movimientos','Cada abono con su fecha, su concepto y su respaldo.',button('Registrar abono','new-payment','primary','plus'))+`<div class="toolbar"><label class="search">${icon('search')}<input id="search" aria-label="Buscar movimiento" placeholder="Buscar por cliente o medio de pago…" value="${esc(query)}"></label>${button('Exportar CSV','csv','','download')}</div><section class="panel">${list.length?paymentsTable(list):empty('Sin movimientos para mostrar','Los abonos que registres aparecerán aquí.')}</section>`;}
function clientView(id){const c=client(id);if(!c)return empty('Cliente no encontrado','Vuelve a la lista de clientes.');const ls=data.loans.filter(l=>l.clientId===id),t=totals(ls),ps=data.payments.filter(p=>ls.some(l=>l.id===p.loanId));return `<button class="back" data-action="clients">${icon('back')} Volver a clientes</button><div class="page-heading"><div class="client-head"><span class="person-avatar">${esc(initials(c.name))}</span><div><div class="eyebrow">HOJA DE VIDA DEL CLIENTE</div><h1>${esc(c.name)}</h1><p>${esc(c.phone||'Sin teléfono')} · Cliente desde ${date(c.createdAt)}</p></div></div><div class="buttons">${button('Editar ficha','edit-client','','file',`data-id="${esc(id)}"`)}${button('Nuevo préstamo','new-loan','primary','plus',`data-id="${esc(id)}"`)}</div></div>`+stats([{label:'Capital desembolsado',value:money(t.principal),icon:'wallet',foot:`${ls.length} préstamos registrados`},{label:'Capital pendiente',value:money(t.balance),icon:'clock',foot:'Sin sumar intereses futuros'},{label:'Capital recuperado',value:money(t.paid),icon:'check',foot:'Abonos registrados a capital'},{label:'Intereses recibidos',value:money(t.interest),icon:'up',foot:'Pagos de intereses registrados'}])+`<div class="detail-grid"><div class="detail-cards">${ls.map((l,i)=>{const a=ledger(l,data.payments),progress=a.paidPrincipal/l.principal*100;return `<section class="panel"><div class="loan-summary"><div class="loan-top"><div><strong>Préstamo ${String(i+1).padStart(2,'0')}</strong><small>Desembolsado el ${date(l.start)}</small></div>${badge(l)}</div><div class="loan-numbers"><div><small>MONTO INICIAL</small><strong>${money(l.principal)}</strong></div><div><small>CAPITAL PENDIENTE</small><strong>${money(a.balance)}</strong></div><div><small>CUOTA INICIAL</small><strong>${money(installment(l.principal,l.rate,l.months))}</strong></div></div><div class="progress"><span style="width:${Math.min(100,progress)}%"></span></div><div class="progress-label"><span>${Math.round(progress)}% del capital recuperado</span><span>${l.months} cuotas · ${l.rate.toLocaleString('es-CO')}% mensual</span></div><p class="method-label">Cuota fija con interés sobre saldo. ${esc(l.note)}</p><div class="loan-actions">${a.balance?button('Registrar abono','new-payment','primary','plus',`data-id="${esc(l.id)}"`):'<span class="badge blue">Capital recuperado</span>'}${button('Ver calendario','schedule','','calendar',`data-id="${esc(l.id)}"`)}</div></div></section>`;}).join('')||`<section class="panel">${empty('Su historia empieza aquí','Agrega el primer préstamo de este cliente.')}</section>`}<section class="panel"><div class="panel-heading"><div><h2>Historial de abonos</h2><p>Capital e intereses, siempre separados.</p></div><span class="tag">${ps.filter(p=>!p.reversed).length} abonos</span></div>${ps.length?paymentsTable(ps,false):empty('Todavía no hay abonos','Registra el primer pago cuando lo recibas.')}</section></div><aside class="panel" style="align-self:start"><div class="panel-heading"><h2>Datos del cliente</h2></div><div class="info-list"><div><small>NOMBRE COMPLETO</small><p>${esc(c.name)}</p></div><div><small>TELÉFONO</small><p>${esc(c.phone||'Sin registrar')}</p></div><div><small>OBSERVACIONES</small><p>${esc(c.note||'Sin observaciones.')}</p></div><div><small>ESTADO</small>${clientBadge(c)}</div></div><div class="financial-note">Esta ficha contiene registros de demostración guardados en este navegador.</div></aside></div>`;}
function settingsView(){return heading('Tu espacio','Identidad, respaldos y lo que viene para tu app.','','CONFIGURACIÓN')+`<div class="settings-grid"><section class="panel"><div class="panel-heading"><h2>La esencia de Crispy</h2><span class="tag">Tu marca</span></div><div class="settings-body"><p>Verde para las acciones, blanco para dar claridad, azul para la información y un toque naranja para llamar la atención.</p><div class="palette"><span class="swatch" style="background:#087754">#087754</span><span class="swatch white" style="background:#fff">#FFFFFF</span><span class="swatch" style="background:#3675a6">#3675A6</span><span class="swatch" style="background:#dd8c38">#DD8C38</span></div><img src="assets/marca.png" class="brand-image" alt="Referencia original de la marca Crispy Crédito, con mascota, verde, azul y naranja."></div></section><div class="detail-cards"><section class="panel"><div class="panel-heading"><h2>Tus registros, contigo</h2>${icon('download')}</div><div class="settings-body"><p>En esta versión los datos viven en este navegador. Descarga un respaldo JSON para recuperarlos después o en otro equipo.</p>${button('Descargar respaldo','export','primary','download')}${button('Importar respaldo','import','','file')}<input id="import-file" type="file" accept="application/json,.json" hidden><p style="margin-top:10px">Importar reemplaza los datos de esta demo, después de tu confirmación. No compartas respaldos con información privada.</p></div></section><section class="panel"><div class="panel-heading"><h2>El siguiente paso</h2>${icon('shield')}</div><div class="settings-body"><p>Conectar Supabase para tener correo y contraseña reales, acceso restringido y los mismos registros desde el celular y el computador. Esta demo no recoge contraseñas ni tiene conexión a Supabase.</p>${button('Ver pantalla de acceso','access','','arrow')}</div></section><section class="panel"><div class="panel-heading"><h2>Empezar de nuevo</h2></div><div class="settings-body"><p>Puedes recuperar los datos ficticios originales o dejar la demo vacía para explorar desde cero.</p>${button('Restaurar ejemplos','reset','','arrows')}${button('Dejar demo vacía','clear','danger')}</div></section></div></div>`;}
function render(){const r=route(),pages={inicio:'Resumen',clientes:'Clientes',prestamos:'Préstamos',movimientos:'Movimientos',configuracion:'Mi espacio',cliente:'Ficha del cliente'};$('#crumb').textContent=pages[r.page]||'Resumen';$('#nav').innerHTML=[['inicio','Resumen','grid'],['clientes','Clientes','users'],['prestamos','Préstamos','wallet'],['movimientos','Movimientos','arrows'],['configuracion','Mi espacio','settings']].map(([id,label,ico])=>`<a class="nav-item ${(r.page===id||(id==='clientes'&&r.page==='cliente'))?'active':''}" href="#${id}">${icon(ico)}${label}${id==='clientes'?`<span class="nav-count">${data.clients.length}</span>`:''}</a>`).join('');$('#content').innerHTML=(!storageAvailable?'<div class="error-notice">No pudimos recuperar o guardar los datos locales. Descarga un respaldo antes de cerrar.</div>':'')+({inicio:overview,clientes:clientsView,prestamos:loansView,movimientos:paymentsView,configuracion:settingsView,cliente:()=>clientView(r.id)}[r.page]||overview)();}
function modal(title,subtitle,body){$('#modal-content').innerHTML=`<div class="modal-head"><div><h2>${title}</h2><p>${subtitle}</p></div><button class="icon-button" data-action="close" aria-label="Cerrar">×</button></div><div class="modal-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();}
const field=(id,label,html,full=false)=>`<div class="field ${full?'full':''}"><label for="${id}">${label}</label>${html}</div>`;
const input=(name,attrs='')=>`<input id="${name}" name="${name}" ${attrs}>`;
const actions=(label)=>`<div id="form-error"></div><div class="form-actions">${button('Cancelar','close') }<button class="btn primary" type="submit">${icon('check')}${label}</button></div>`;
function clientForm(id){const c=client(id);modal(c?'Editar ficha':'Un nuevo comienzo',c?'Actualiza los datos de esta persona.':'Agrega un cliente y mantén su historia organizada.',`<form id="client-form" data-id="${esc(id||'')}"><div class="form-grid">${field('name','Nombre completo *',input('name',`required maxlength="100" autocomplete="name" placeholder="Ej. Laura Gómez" value="${esc(c?.name||'')}"`),true)}${field('phone','Teléfono',input('phone',`type="tel" maxlength="30" autocomplete="tel" placeholder="Ej. 300 123 4567" value="${esc(c?.phone||'')}"`),true)}${field('note','Observaciones',`<textarea id="note" name="note" maxlength="1000" placeholder="Algún detalle que quieras recordar…">${esc(c?.note||'')}</textarea>`,true)}</div>${actions(c?'Guardar cambios':'Agregar cliente')}</form>`);}
function loanForm(clientId){if(!data.clients.length){toast('Agrega primero un cliente.');clientForm();return;}modal('Un nuevo préstamo','Define el acuerdo y revisa la simulación antes de guardarlo.',`<form id="loan-form"><div class="form-grid">${field('clientId','Cliente *',`<select id="clientId" name="clientId" required><option value="">Selecciona una persona</option>${data.clients.map(c=>`<option value="${esc(c.id)}" ${c.id===clientId?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`,true)}${field('principal','Monto a prestar (COP) *',input('principal','type="number" min="1" max="1000000000000" step="1" required placeholder="1000000"'))}${field('start','Fecha de desembolso *',input('start',`type="date" required value="${today()}"`))}${field('months','Número de cuotas mensuales *',input('months','type="number" min="1" max="120" step="1" required placeholder="6"'))}${field('rate','Interés mensual (%) *',input('rate','type="number" min="0" max="1000" step="0.001" required placeholder="0 si no cobra intereses"'))}${field('note','Observaciones del acuerdo',`<textarea id="note" name="note" maxlength="1000" placeholder="Detalles del préstamo…"></textarea>`,true)}</div><div class="help-box">Método de esta simulación: <b>cuota mensual fija con interés sobre el capital pendiente</b>. Primera cuota un mes después del desembolso. Sin seguros, comisiones ni mora automática. Ajustaremos este método a tu forma de prestar.</div><div id="simulation" class="simulation"><div class="span">Completa monto, cuotas e interés para ver la simulación.</div></div>${actions('Guardar préstamo')}</form>`);}
function updateSimulation(){const f=$('#loan-form');if(!f)return;try{const p=+f.elements.principal.value,n=+f.elements.months.value,rate=+f.elements.rate.value;if(f.elements.rate.value==='')throw Error();const q=installment(p,rate,n),plan=schedule({principal:p,months:n,rate,start:f.elements.start.value||today()}),total=plan.reduce((s,x)=>s+x.total,0);$('#simulation').innerHTML=`<div><small>CUOTA MENSUAL ESTIMADA</small><strong>${money(q)}</strong></div><div><small>TOTAL DEL PLAN INICIAL</small><strong>${money(total)}</strong></div><div class="span">Intereses del plan: ${money(total-p)}. La última cuota se ajusta por redondeo. Las tasas son ingresadas por ti.</div>`;}catch{$('#simulation').innerHTML='<div class="span">Completa monto, cuotas e interés válidos para ver la simulación.</div>';}}
function paymentForm(loanId){const eligible=data.loans.filter(l=>ledger(l,data.payments).balance>0);if(!eligible.length){toast('Primero necesitas un préstamo con saldo pendiente.');return;}modal('Registrar un abono','Un pago registrado es una cuenta más clara.',`<form id="payment-form"><div class="form-grid">${field('loanId','Préstamo *',`<select id="loanId" name="loanId" required>${eligible.map(l=>`<option value="${esc(l.id)}" ${l.id===loanId?'selected':''}>${esc(client(l.clientId).name)} · ${money(l.principal)} · ${date(l.start)}</option>`).join('')}</select>`,true)}${field('capital','Abono a capital (COP) *',input('capital','type="number" min="0" step="1" required value="0"'))}${field('interest','Pago de intereses (COP) *',input('interest','type="number" min="0" max="1000000000000" step="1" required value="0"'))}${field('date','Fecha del pago *',input('date',`type="date" max="${today()}" required value="${today()}"`))}${field('method','Medio de pago',`<select id="method" name="method"><option>Transferencia</option><option>Efectivo</option><option>Nequi</option><option>Otro</option></select>`)}${field('note','Nota o referencia',`<textarea id="note" name="note" maxlength="1000" placeholder="Ej. Transferencia recibida, referencia…"></textarea>`,true)}</div><div id="payment-summary" class="help-box"></div><div class="help-box blue">Tú indicas cuánto corresponde a capital e intereses según el acuerdo. Un pago de intereses no reduce el capital. Esta versión no calcula mora ni modifica automáticamente el calendario por abonos extra.</div>${actions('Guardar abono')}</form>`);updatePaymentSummary();}
function updatePaymentSummary(){const f=$('#payment-form');if(!f)return;const l=loan(f.elements.loanId.value),balance=ledger(l,data.payments).balance;f.elements.capital.max=balance;f.elements.date.min=l.start;const capital=+f.elements.capital.value,interest=+f.elements.interest.value;$('#payment-summary').innerHTML=`Capital pendiente: <b>${money(balance)}</b><br>Total del abono: <b>${money(capital+interest)}</b> · Capital después del abono: <b>${money(Math.max(0,balance-capital))}</b>`;}
function showSchedule(id){const l=loan(id);modal('Calendario del préstamo',`${esc(client(l.clientId).name)} · ${l.months} cuotas mensuales · ${l.rate}% mensual`, `<p class="schedule-note">Plan original al desembolsar, con cuota fija e interés sobre saldo. No es un estado de cuenta actualizado: los abonos extraordinarios no recalculan este calendario.</p><div class="table-wrap"><table><thead><tr><th>CUOTA / FECHA</th><th>CAPITAL</th><th>INTERÉS</th><th>TOTAL</th><th>SALDO</th></tr></thead><tbody>${schedule(l).map(r=>`<tr><td>${r.number} · ${date(r.date)}</td><td>${money(r.capital)}</td><td>${money(r.interest)}</td><td class="cell-money">${money(r.total)}</td><td>${money(r.balance)}</td></tr>`).join('')}</tbody></table></div><div class="form-actions">${button('Cerrar','close','primary')}</div>`);}
function accessPreview(){modal('Bienvenido a Crispy Crédito','Vista propuesta para el acceso a tu app.',`<div class="access-layout"><img src="assets/marca.png" alt="Marca Crispy Crédito"><div><div class="eyebrow">TU ESPACIO PERSONAL</div><h3>Tus sueños,<br>tus cuentas claras.</h3><p>La versión conectada tendrá inicio de sesión con correo y contraseña. En este prototipo puedes recorrer la app sin ingresar credenciales.</p>${button('Explorar demostración','close','primary','arrow')}</div></div><div class="help-box">Vista de diseño. El login de Supabase todavía no está conectado. Esta exportación no incluye autenticación activa. Publicarla en Vercel no restringe el acceso por sí solo.</div>`);}
function showPayment(id){const p=data.payments.find(p=>p.id===id),l=loan(p.loanId);modal('Detalle del abono',esc(client(l.clientId).name),`<div class="info-list"><div><small>FECHA</small><p>${date(p.date)}</p></div><div><small>CAPITAL / INTERESES</small><p>${money(p.capital)} / ${money(p.interest)}</p></div><div><small>TOTAL RECIBIDO</small><p><b>${money(p.capital+p.interest)}</b></p></div><div><small>MEDIO DE PAGO</small><p>${esc(p.method)}</p></div><div><small>NOTA</small><p>${esc(p.note||'Sin observaciones.')}</p></div></div><div class="help-box">Si hubo un error, puedes anular este abono. El registro permanecerá en el historial y su capital dejará de descontarse.</div><div class="form-actions">${button('Cerrar','close')}${button('Anular abono','reverse','danger','',`data-id="${esc(p.id)}"`)}</div>`);}
function confirmDialog(title,text,action,label,attrs=''){modal(title,text,`<div class="form-actions">${button('Cancelar','close')}${button(label,action,'primary','',attrs)}</div>`);}
function download(text,name,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function exportData(){download(JSON.stringify(data,null,2),`crispy-credito-respaldo-${today()}.json`,'application/json');toast('Respaldo descargado. Guárdalo en un lugar privado.');}
function exportCsv(){const quote=v=>'"'+String(v).replace(/"/g,'""')+'"';const rows=[['Fecha','Cliente','Capital COP','Intereses COP','Total COP','Medio','Estado','Nota'],...data.payments.map(p=>[p.date,client(loan(p.loanId).clientId).name,p.capital,p.interest,p.capital+p.interest,p.method,p.reversed?'Anulado':'Registrado',p.note])];const safe=v=>typeof v==='string'&&/^[=+@\-\t\r]/.test(v)?"'"+v:v;download('\uFEFF'+rows.map(r=>r.map(v=>quote(safe(v))).join(';')).join('\r\n'),`crispy-credito-movimientos-${today()}.csv`,'text/csv;charset=utf-8');}
function validDate(v){return typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!isNaN(Date.parse(v))&&new Date(v+'T12:00:00Z').toISOString().slice(0,10)===v;}
function validateImport(d){
  if(d?.version!==1||!['clients','loans','payments'].every(k=>Array.isArray(d[k])&&d[k].length<=10000))throw Error('El archivo no es un respaldo válido de Crispy Crédito.');
  const str=(v,max=1000)=>typeof v==='string'&&v.length<=max;
  const ids=new Set();for(const item of [...d.clients,...d.loans,...d.payments]){if(!str(item.id,100)||!item.id||ids.has(item.id))throw Error('El respaldo contiene identificadores inválidos.');ids.add(item.id);}
  const amount=v=>Number.isSafeInteger(v)&&v>=0&&v<=1e12;
  for(const c of d.clients)if(!str(c.name,100)||!c.name.trim()||!str(c.phone,30)||!str(c.note)||!validDate(c.createdAt))throw Error('El respaldo contiene un cliente inválido.');
  for(const l of d.loans){if(!d.clients.some(c=>c.id===l.clientId)||!amount(l.principal)||!l.principal||!Number.isFinite(l.rate)||l.rate<0||l.rate>1000||!validDate(l.start)||!str(l.note))throw Error('El respaldo contiene un préstamo inválido.');installment(l.principal,l.rate,l.months);}
  for(const p of d.payments){const l=d.loans.find(l=>l.id===p.loanId);if(!l||!amount(p.capital)||!amount(p.interest)||p.capital+p.interest<=0||!validDate(p.date)||p.date<l.start||p.date>today()||!str(p.method,100)||!str(p.note)||!str(p.createdAt,100)||isNaN(Date.parse(p.createdAt))||(p.reversed!==undefined&&typeof p.reversed!=='boolean'))throw Error('El respaldo contiene un abono inválido.');}
  for(const l of d.loans)if(d.payments.filter(p=>p.loanId===l.id&&!p.reversed).reduce((s,p)=>s+p.capital,0)>l.principal)throw Error('El respaldo abona más capital que el prestado.');
  return {version:1,clients:d.clients.map(c=>({id:c.id,name:c.name,phone:c.phone,note:c.note,createdAt:c.createdAt})),loans:d.loans.map(l=>({id:l.id,clientId:l.clientId,principal:l.principal,rate:l.rate,months:l.months,start:l.start,note:l.note})),payments:d.payments.map(p=>({id:p.id,loanId:p.loanId,capital:p.capital,interest:p.interest,date:p.date,method:p.method,note:p.note,createdAt:p.createdAt,reversed:!!p.reversed}))};
}
let pendingImport;
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;
  const handlers={close:closeModal,clients:()=>go('clientes'),payments:()=>go('movimientos'),client:()=>go('cliente/'+id),'new-client':()=>clientForm(),'edit-client':()=>clientForm(id),'new-loan':()=>loanForm(id),'new-payment':()=>paymentForm(id),schedule:()=>showSchedule(id),export:exportData,csv:exportCsv,access:accessPreview,'payment-detail':()=>showPayment(id),filter:()=>{filter=el.dataset.value;render();},import:()=>$('#import-file').click(),reset:()=>confirmDialog('¿Restaurar los ejemplos?','Esto reemplazará tus registros locales. Descarga un respaldo si deseas conservarlos.','confirm-reset','Sí, restaurar'),clear:()=>confirmDialog('¿Dejar la demo vacía?','Se quitarán los registros de este navegador. Descarga un respaldo antes si los necesitas.','confirm-clear','Sí, vaciar demo'),'confirm-reset':()=>{data=seed();persist();closeModal();render();toast('Ejemplos restaurados.');},'confirm-clear':()=>{data={version:1,clients:[],loans:[],payments:[]};persist();closeModal();render();toast('Listo. Puedes empezar desde cero.');},reverse:()=>confirmDialog('¿Anular este abono?','El registro quedará marcado como anulado y el capital se restablecerá.','confirm-reverse','Sí, anular',`data-id="${esc(id)}"`),'confirm-reverse':()=>{data.payments.find(p=>p.id===id).reversed=true;persist();closeModal();render();toast('Abono anulado. Se conserva en el historial.');},'confirm-import':()=>{data=pendingImport;pendingImport=null;persist();closeModal();render();toast('Respaldo importado.');}};
  handlers[a]?.();
});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}if(e.target.closest('#loan-form'))updateSimulation();if(e.target.closest('#payment-form'))updatePaymentSummary();});
document.addEventListener('change',async e=>{if(e.target.closest('#payment-form'))updatePaymentSummary();if(e.target.id!=='import-file')return;const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('El respaldo debe pesar menos de 5 MB.');pendingImport=validateImport(JSON.parse(await file.text()));confirmDialog('¿Importar este respaldo?',`${pendingImport.clients.length} clientes, ${pendingImport.loans.length} préstamos y ${pendingImport.payments.length} abonos. Reemplazará los registros de esta demo.`,'confirm-import','Sí, importar');}catch(err){toast(err.message||'No pudimos leer el respaldo.');}e.target.value='';});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(!['client-form','loan-form','payment-form'].includes(f.id))return;try{const v=Object.fromEntries(new FormData(f));let destination;
  if(f.id==='client-form'){if(!v.name.trim())throw Error('Escribe el nombre del cliente.');const id=f.dataset.id,c=client(id);if(c)Object.assign(c,{name:v.name.trim(),phone:v.phone.trim(),note:v.note.trim()});else{const newC={id:uid(),name:v.name.trim(),phone:v.phone.trim(),note:v.note.trim(),createdAt:today()};data.clients.push(newC);destination='cliente/'+newC.id;}}
  if(f.id==='loan-form'){const principal=+v.principal,months=+v.months,rate=+v.rate;installment(principal,rate,months);if(!client(v.clientId)||!validDate(v.start)||!Number.isSafeInteger(principal)||principal>1e12)throw Error('Revisa los datos del préstamo.');data.loans.push({id:uid(),clientId:v.clientId,principal,rate,months,start:v.start,note:v.note.trim()});destination='cliente/'+v.clientId;}
  if(f.id==='payment-form'){const l=loan(v.loanId),capital=+v.capital,interest=+v.interest;if(!l||!Number.isSafeInteger(capital)||!Number.isSafeInteger(interest)||capital<0||interest<0||interest>1e12||capital+interest<=0)throw Error('El abono debe tener un valor positivo, en pesos enteros.');if(capital>ledger(l,data.payments).balance)throw Error('El abono a capital supera el capital pendiente.');if(!validDate(v.date)||v.date<l.start||v.date>today())throw Error('La fecha debe estar entre el desembolso y hoy.');data.payments.push({id:uid(),loanId:l.id,capital,interest,date:v.date,method:v.method,note:v.note.trim(),createdAt:new Date().toISOString()});destination='cliente/'+l.clientId;}
  persist();closeModal();destination?go(destination):render();toast(f.id==='client-form'?'Ficha del cliente guardada.':f.id==='loan-form'?'Préstamo registrado.':'Abono registrado. Capital e intereses actualizados.');
}catch(err){$('#form-error').innerHTML=`<div class="form-error" role="alert">${esc(err.message)}</div>`;}});
window.addEventListener('hashchange',()=>{query='';filter='todos';$('#sidebar').classList.remove('open');render();window.scrollTo(0,0);});
$('#menu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#mobile-shade').addEventListener('click',()=>$('#sidebar').classList.remove('open'));
$('#profile').addEventListener('click',()=>go('configuracion'));
$('#access-preview').addEventListener('click',accessPreview);
$('#help').addEventListener('click',()=>modal('Tu app, en construcción','Una primera versión para explorar y ajustar contigo.',`<div class="settings-body"><p>Los clientes y pagos iniciales son ficticios. Puedes agregar clientes, crear préstamos, registrar abonos y descargar un respaldo.</p><p>Los registros se guardan solo en este navegador. El login de Supabase y la sincronización entre dispositivos aún no están conectados. No ingreses información sensible en esta prueba.</p><p>El calendario usa cuota fija con interés sobre saldo, sin comisiones ni mora. Los abonos se separan manualmente entre capital e intereses.</p>${button('Entendido','close','primary')}</div>`));
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
render();
